package got.wildlife; import got.GOTItems; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.level.Level; public final class GOTWalrusEntity extends GOTDefensiveAnimalEntity { public GOTWalrusEntity(EntityType<? extends net.minecraft.world.entity.animal.Animal> t,Level l){super(t,l);xpReward=5;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,50).add(Attributes.MOVEMENT_SPEED,.18).add(Attributes.ATTACK_DAMAGE,5).add(Attributes.FOLLOW_RANGE,20);} @Override public boolean canFreeze(){return false;} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(GOTItems.FUR.get());for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(isOnFire()?GOTItems.WALRUS_LARD_COOKED.get():GOTItems.WALRUS_LARD_RAW.get());} }